import{_ as t,o as e,c as r,a5 as a}from"./chunks/framework.CnBNXlt7.js";const m=JSON.parse('{"title":"2025/09/08","description":"","frontmatter":{},"headers":[],"relativePath":"trip/journey/20250908.md","filePath":"trip/journey/20250908.md","lastUpdated":1763305726000}'),o={name:"trip/journey/20250908.md"};function s(_,p,c,i,n,l){return e(),r("div",null,[...p[0]||(p[0]=[a('<h1 id="_2025-09-08" tabindex="-1">2025/09/08 <a class="header-anchor" href="#_2025-09-08" aria-label="Permalink to &quot;2025/09/08&quot;">​</a></h1><p>开车去桂林北站<br> 没看到地方停车，停路边还被抓拍警告了<br> 还好停的时间短，没有挨罚单</p><p>去商务候车厅，<br> 抠门啊，说是只给商务座的人零食和水，其他软卧、一等卧不给，我笑了</p><p>休息片刻，就上车了</p><p>对比了一下一等卧和软卧，提升比较大<br> 但是晚上睡觉噪音还是不能接受</p><p>这个晚上睡不好，主要是有人老是关空调，被频繁热醒，还有人不关灯睡觉，我真的</p><p>三个仙女，手机也不静音，一直叮叮催命符</p><p>最差的一次一等卧体验，真别给我包厢里分仙女了，一晚上不停的关空调，给我热醒了无数次，手机也不静音，半夜还在叮叮叮</p><div class="tip custom-block"><p class="custom-block-title">记录一下一等卧</p><p>一切对比都是相较于软卧。<br> 比软卧软太多，很舒服的床铺。床铺更宽，更软，可能就宽10cm。<br> 每个床铺都有两个usb口，都是5V1A<br> 上车送水，矿泉水一瓶，500ml</p><p>但是有一个异味，不知道是什么东西散发出来的，就是新车，新味儿</p><p>很稳<br> 毕竟是复兴号</p><p>动车不能吸烟，太好了哈哈</p><p>并且，似乎没有隔断，跟其他车厢没有隔断。</p></div>',9)])])}const b=t(o,[["render",s]]);export{m as __pageData,b as default};
